Which solid does this net make?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw (0,0) rectangle (1.2,2); \draw (1.2,0) rectangle (2.4,2); \draw (2.4,0) rectangle (3.6,2);
\draw (1.2,2)--(1.8,{2+0.6*sqrt(3)})--(2.4,2)--cycle; \draw (1.2,0)--(1.8,{-0.6*sqrt(3)})--(2.4,0)--cycle;
\end{tikzpicture}
[/tikz]

What solid does this net make?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw (0,0) rectangle (2,2); \draw (0,0)--(1,-1.5)--(2,0)--cycle; \draw (2,0)--(3.5,1)--(2,2)--cycle; \draw (2,2)--(1,3.5)--(0,2)--cycle; \draw (0,2)--(-1.5,1)--(0,0)--cycle;
\end{tikzpicture}
[/tikz]

Which solid does this net make?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\foreach \i in {0,...,4}{\draw (\i,0) rectangle ++(1,2);}
\draw (2,2)--(3,2)--({3+cos(72)},{2+sin(72)})--(2.5,{2+sin(72)+sin(36)})--({2-cos(72)},{2+sin(72)})--cycle;
\draw (2,0)--(3,0)--({3+cos(72)},{-sin(72)})--(2.5,{-sin(72)-sin(36)})--({2-cos(72)},{-sin(72)})--cycle;
\end{tikzpicture}
[/tikz]

Which solid does this net make?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw (0,0) rectangle ({1.8*pi},2.2); \draw (0.9,-0.9) circle (0.9); \draw ({1.8*pi-0.9},3.1) circle (0.9);
\end{tikzpicture}
[/tikz]

Which solid does this net make?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\foreach \x/\y in {0/0,1/0,1/1,2/1,2/2,3/2}{\draw (\x,\y) rectangle ++(1,1);}
\end{tikzpicture}
[/tikz]

Which prism does this net make?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw (0,0) rectangle (2.4,1.5); \draw (2.4,0) rectangle (3.6,1.5); \draw (3.6,0) rectangle (4.8,1.5); \draw (4.8,0) rectangle (6,1.5);
\draw (0,1.5)--(2.4,1.5)--(1.8,{1.5+0.6*sqrt(3)})--(0.6,{1.5+0.6*sqrt(3)})--cycle;
\draw (0,0)--(2.4,0)--(1.8,{-0.6*sqrt(3)})--(0.6,{-0.6*sqrt(3)})--cycle;
\end{tikzpicture}
[/tikz]
